static void config_json(const drone_config_t*c,char*b,size_t n){snprintf(b,n,"{\"version\":%lu,\"roll\":{\"kp\":%.6f,\"ki\":%.6f,\"kd\":%.6f},\"pitch\":{\"kp\":%.6f,\"ki\":%.6f,\"kd\":%.6f},\"yaw\":{\"kp\":%.6f,\"ki\":%.6f,\"kd\":%.6f},\"max_angle_deg\":%.1f,\"max_rate_dps\":%.1f,\"max_motor_output\":%.2f,\"complementary_alpha\":%.3f,\"failsafe_ms\":%u,\"acro\":%s,\"motor_map\":[%u,%u,%u,%u]}",(unsigned long)c->version,c->roll.kp,c->roll.ki,c->roll.kd,c->pitch.kp,c->pitch.ki,c->pitch.kd,c->yaw.kp,c->yaw.ki,c->yaw.kd,c->max_angle_deg,c->max_rate_dps,c->max_motor_output,c->complementary_alpha,c->failsafe_ms,c->acro?"true":"false",c->motor_map[0]+1,c->motor_map[1]+1,c->motor_map[2]+1,c->motor_map[3]+1);}
