static esp_err_t schema_get(httpd_req_t*r){static const char schema[]={"{\"pid\":{\"kp\":{\"min\":0,\"max\":20},\"ki\":{\"min\":0,\"max\":10},\"kd\":{\"min\":0,\"max\":2}},\"max_angle_deg\":{\"min\":5,\"max\":45},\"max_rate_dps\":{\"min\":30,\"max\":720},\"max_motor_output\":{\"min\":0.1,\"max\":1},\"complementary_alpha\":{\"min\":0.9,\"max\":0.999},\"failsafe_ms\":{\"min\":100,\"max\":1000,\"integer\":true}}"};httpd_resp_set_type(r,"application/json");return httpd_resp_sendstr(r,schema);}
static bool num(cJSON*o,const char*k,float*x){cJSON*v=cJSON_GetObjectItemCaseSensitive(o,k);if(!cJSON_IsNumber(v))return false;*x=(float)v->valuedouble;return true;}
static bool config_keys_valid(cJSON*j){static const char*allowed[]={"version","roll","pitch","yaw","max_angle_deg","max_rate_dps","max_motor_output","complementary_alpha","failsafe_ms","acro","motor_map"};for(cJSON*v=j->child;v;v=v->next){bool known=false;for(size_t i=0;i<sizeof(allowed)/sizeof(allowed[0]);i++)if(v->string&&strcmp(v->string,allowed[i])==0){known=true;break;}if(!known)return false;}cJSON*version=cJSON_GetObjectItemCaseSensitive(j,"version");return !version||(cJSON_IsNumber(version)&&version->valueint==(int)cfg->version);}
static esp_err_t cfg_post(httpd_req_t*r){if(strcmp(st->state,"DISARMED")!=0){httpd_resp_set_status(r,"409 Conflict");return httpd_resp_sendstr(r,"Configuration changes require DISARMED state");}if(r->content_len>1024)return httpd_resp_send_err(r,HTTPD_400_BAD_REQUEST,"Request too large");char*b=calloc(1,r->content_len+1);if(!b)return ESP_ERR_NO_MEM;size_t got=0;while(got<r->content_len){int n=httpd_req_recv(r,b+got,r->content_len-got);if(n<=0){free(b);return httpd_resp_send_err(r,HTTPD_400_BAD_REQUEST,"Incomplete request body");}got+=(size_t)n;}cJSON*j=cJSON_Parse(b);free(b);if(!j)return httpd_resp_send_err(r,HTTPD_400_BAD_REQUEST,"Invalid JSON");drone_config_t next;config_snapshot(cfg,&next);cJSON*o;bool ok=cJSON_IsObject(j)&&config_keys_valid(j);const char*names[]={"roll","pitch","yaw"};whoopy_pid_cfg_t*ps[]={&next.roll,&next.pitch,&next.yaw};for(int i=0;i<3&&ok;i++){o=cJSON_GetObjectItemCaseSensitive(j,names[i]);ok=cJSON_IsObject(o)&&num(o,"kp",&ps[i]->kp)&&num(o,"ki",&ps[i]->ki)&&num(o,"kd",&ps[i]->kd);}ok=ok&&num(j,"max_angle_deg",&next.max_angle_deg)&&num(j,"max_rate_dps",&next.max_rate_dps)&&num(j,"max_motor_output",&next.max_motor_output)&&num(j,"complementary_alpha",&next.complementary_alpha);cJSON*to=cJSON_GetObjectItemCaseSensitive(j,"failsafe_ms");cJSON*acro=cJSON_GetObjectItemCaseSensitive(j,"acro");cJSON*map=cJSON_GetObjectItemCaseSensitive(j,"motor_map");ok=ok&&cJSON_IsNumber(to)&&floor(to->valuedouble)==to->valuedouble&&to->valueint>=100&&to->valueint<=1000&&cJSON_IsBool(acro)&&cJSON_IsArray(map)&&cJSON_GetArraySize(map)==4;if(ok){next.failsafe_ms=(uint16_t)to->valueint;next.acro=cJSON_IsTrue(acro);for(int i=0;i<4;i++){cJSON*v=cJSON_GetArrayItem(map,i);if(!cJSON_IsNumber(v)||floor(v->valuedouble)!=v->valuedouble||v->valueint<1||v->valueint>4){ok=false;break;}next.motor_map[i]=(uint8_t)(v->valueint-1);}}cJSON_Delete(j);if(!ok||!config_valid(&next))return httpd_resp_send_err(r,HTTPD_400_BAD_REQUEST,"Unknown, missing, or out-of-range PID/config value");esp_err_t save_err=config_save(&next);if(save_err!=ESP_OK){httpd_resp_set_status(r,"500 Internal Server Error");return httpd_resp_sendstr(r,"NVS save failed; settings were not applied");}config_replace(cfg,&next);imu_set_filter_alpha(next.complementary_alpha);st->config_status="saved to NVS";st->save_status="saved to NVS";return httpd_resp_sendstr(r,"Applied and saved to non-volatile storage");}
static esp_err_t receiver_post(httpd_req_t*r){if(strcmp(st->state,"DISARMED")!=0||*is_armed){httpd_resp_set_status(r,"409 Conflict");return httpd_resp_sendstr(r,"Receiver mode changes require DISARMED state");}if(r->content_len<1||r->content_len>64)return httpd_resp_send_err(r,HTTPD_400_BAD_REQUEST,"Invalid request size");char body[65]={0};size_t got=0;while(got<r->content_len){int n=httpd_req_recv(r,body+got,r->content_len-got);if(n<=0)return httpd_resp_send_err(r,HTTPD_400_BAD_REQUEST,"Incomplete request body");got+=(size_t)n;}cJSON*j=cJSON_Parse(body);cJSON*m=j?cJSON_GetObjectItemCaseSensitive(j,"mode"):NULL;receiver_mode_t mode;if(cJSON_IsString(m)&&strcmp(m->valuestring,"nrf24")==0)mode=RECEIVER_NRF24;else if(cJSON_IsString(m)&&strcmp(m->valuestring,"elrs")==0)mode=RECEIVER_ELRS;else{if(j)cJSON_Delete(j);return httpd_resp_send_err(r,HTTPD_400_BAD_REQUEST,"mode must be nrf24 or elrs");}cJSON_Delete(j);esp_err_t save_err=config_save_receiver_mode((uint8_t)mode);if(save_err!=ESP_OK){httpd_resp_set_status(r,"500 Internal Server Error");return httpd_resp_sendstr(r,"NVS save failed; receiver mode was not changed");}radio_set_mode(mode);st->config_status="settings saved to NVS";st->save_status="saved to NVS";return httpd_resp_sendstr(r,mode==RECEIVER_ELRS?"ELRS / CRSF selected and saved":"Built-in nRF24L01 selected and saved");}
static esp_err_t save_post(httpd_req_t*r){if(strcmp(st->state,"DISARMED")!=0){httpd_resp_set_status(r,"409 Conflict");return httpd_resp_sendstr(r,"Disarm first");}drone_config_t c;config_snapshot(cfg,&c);esp_err_t e=config_save(&c);st->save_status=e==ESP_OK?"saved to NVS":"save failed";if(e!=ESP_OK){httpd_resp_set_status(r,"500 Internal Server Error");return httpd_resp_sendstr(r,"Save failed; configuration remains temporary");}return httpd_resp_sendstr(r,"Saved to flash");}
static esp_err_t defaults_post(httpd_req_t*r){if(strcmp(st->state,"DISARMED")!=0){httpd_resp_set_status(r,"409 Conflict");return httpd_resp_sendstr(r,"Disarm first");}drone_config_t c;config_defaults(&c);esp_err_t e=config_save(&c);if(e!=ESP_OK){httpd_resp_set_status(r,"500 Internal Server Error");return httpd_resp_sendstr(r,"NVS save failed; defaults were not applied");}config_replace(cfg,&c);imu_set_filter_alpha(c.complementary_alpha);st->config_status="defaults saved to NVS";st->save_status="saved to NVS";return httpd_resp_sendstr(r,"Factory defaults applied and saved to non-volatile storage");}
static esp_err_t cal_post(httpd_req_t*r){if(strcmp(st->state,"DISARMED")!=0){httpd_resp_set_status(r,"409 Conflict");return httpd_resp_sendstr(r,"Disarm first");}*cal_req=true;return httpd_resp_sendstr(r,"Calibration queued; status is shown on dashboard");}
void web_config_start(drone_config_t*c,live_status_t*s,volatile bool*cr,volatile bool*a){cfg=c;st=s;cal_req=cr;is_armed=a;size_t ssid_len=strlen(CONFIG_WHOOPY_AP_SSID),pass_len=strlen(CONFIG_WHOOPY_AP_PASSWORD);if(ssid_len==0||ssid_len>32||pass_len<8||pass_len>63){ESP_LOGE(TAG,"AP settings invalid; use SSID 1-32 chars and WPA2 password 8-63 chars");return;}ESP_ERROR_CHECK(esp_netif_init());ESP_ERROR_CHECK(esp_event_loop_create_default());esp_netif_create_default_wifi_ap();wifi_init_config_t w=WIFI_INIT_CONFIG_DEFAULT();ESP_ERROR_CHECK(esp_wifi_init(&w));wifi_config_t ap={.ap={.ssid_len=(uint8_t)ssid_len,.channel=6,.max_connection=2,.authmode=WIFI_AUTH_WPA2_PSK}};strlcpy((char*)ap.ap.ssid,CONFIG_WHOOPY_AP_SSID,sizeof(ap.ap.ssid));strlcpy((char*)ap.ap.password,CONFIG_WHOOPY_AP_PASSWORD,sizeof(ap.ap.password));ESP_ERROR_CHECK(esp_wifi_set_mode(WIFI_MODE_AP));ESP_ERROR_CHECK(esp_wifi_set_config(WIFI_IF_AP,&ap));ESP_ERROR_CHECK(esp_wifi_start());httpd_config_t hc=HTTPD_DEFAULT_CONFIG();hc.stack_size=8192;hc.max_uri_handlers=12;ESP_ERROR_CHECK(httpd_start(&server,&hc));httpd_uri_t u[]={{"/",HTTP_GET,root,NULL},{"/api/status",HTTP_GET,status_get,NULL},{"/api/config",HTTP_GET,cfg_get,NULL},{"/api/config",HTTP_POST,cfg_post,NULL},{"/api/config/defaults",HTTP_GET,defaults_get,NULL},{"/api/schema",HTTP_GET,schema_get,NULL},{"/api/save",HTTP_POST,save_post,NULL},{"/api/defaults",HTTP_POST,defaults_post,NULL},{"/api/calibrate",HTTP_POST,cal_post,NULL},{"/api/receiver",HTTP_POST,receiver_post,NULL}};for(unsigned i=0;i<sizeof(u)/sizeof(u[0]);i++)httpd_register_uri_handler(server,&u[i]);ESP_LOGI(TAG,"AP started on SSID '%s'; HTTP task stack %u bytes",CONFIG_WHOOPY_AP_SSID,(unsigned)hc.stack_size);}
